"use client";

import type { ChartRoot } from "./chart-utils";
import { useMergedRef } from "../lib/form";
import { useCallback, useDeferredValue, useId, useMemo, useRef, useState } from "react";

import { cn } from "../lib/cn";
import { duration } from "../motion/tokens";
import { useSheenReducedMotion } from "../hooks/use-preferences";
import { ChartAnnouncer, ChartEmpty, type TooltipRow } from "./chart-parts";
import { DockHint, dockHintHeight, dockSpace, useInputSource, type Readout } from "./chart-fit";
import { useCoarsePointer } from "../hooks/use-media-query";
import { chartFocusClass, clamp, useElementWidth, resolveInstructions, itemAt } from "./chart-utils";
import { ChartTip, defaultCompact, defaultPercent, useEntrance } from "./heatmap";
import { isolate, useChartDirection, useHitBounds, usePointerReading } from "./chart-pointer";
import {
  fitText,
  glowColor,
  GlowFilter,
  signedText,
  useDockFits,
  useMarkMotion,
  type MarkState,
} from "./kits/histogram-kit/kit";
import { ChartFigure } from "./chart-figure";

import {
  defaultDumbbellChartLabels,
  type DumbbellChartProps,
  dumbbellColors,
  FROM_R,
  TO_R,
  DIMMED,
  TIP,
  type Row,
  resolveRows,
  arrowOf,
  dotPath,
  barD,
  rowDimClass,
  centreOrigin,
} from "./dumbbell-chart/model";
import { dumbbellEntrance, writeDumbbellMark } from "./dumbbell-chart/motion";
import { DumbbellAxis } from "./dumbbell-chart/axis";
import { computeDumbbellLayout, computeSlopeLayout, dumbbellDomain } from "./dumbbell-chart/layout";
import { SLOPE_TIP, ChangeText, SlopeLabels } from "./dumbbell-chart/parts";

export {
  type DumbbellItem,
  type DumbbellChartLabels,
  defaultDumbbellChartLabels,
  type DumbbellChartProps,
  dumbbellColors,
  dumbbellLegend,
  spreadLabels,
} from "./dumbbell-chart/model";
export { type DumbbellTableProps, DumbbellTable } from "./dumbbell-chart/table";
/**
 * Before → after for each item. The dumbbell joins a light "before" dot to a full-colour "after"
 * dot with a bar that brightens in the direction of travel; the slope variant puts the two ends in
 * columns and joins them with lines, labels spread so none collide. Each change is printed with
 * ▲ / ▼ and, by `higherIsBetter`, a success or danger tone, so colour never carries it alone.
 *
 * Hover, tap (tap again to unpin) or arrow through the items. On first view the "after" dot travels
 * out from the "before" dot (slope lines draw left to right); new data glides; re-sorting slides
 * the rows. Instant under reduced motion.
 *
 * Fast: rows are plain SVG moved by one frame loop (useMarkMotion), and reading a row never
 * re-renders them (the others step back with one opacity change each; the row is redrawn on top).
 *
 * Keyboard: Tab focuses the chart; Up and Down move between items, Home and End jump to the first and last, Escape clears.
 * Accessibility: `role="figure"` named by the chart title, with the keyboard hint as its description (`aria-describedby`, and `aria-details` to the `ChartCard` table view); focusable only when interactive; every change is printed with an up or down arrow and a success or danger tone (by `higherIsBetter`), so colour never carries it alone. `DumbbellTable` is the table view.
 * Glass and motion: the plot has no backdrop blur. Reduced motion draws, glides and re-sorts instantly.
 *
 * @example
 * ```tsx
 * import { DumbbellChart } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <DumbbellChart
 *       data={[
 *         { label: "Checkout", from: 3.2, to: 4.1 },
 *         { label: "Search", from: 2.8, to: 3.5 },
 *         { label: "Onboarding", from: 3.9, to: 3.6 },
 *       ]}
 *       fromLabel="Q1"
 *       toLabel="Q2"
 *       aria-label="Satisfaction score, Q1 to Q2"
 *     />
 *   );
 * }
 * ```
 *
 * @see /charts/dumbbell
 */
export function DumbbellChart({
  data: dataProp,
  variant = "dumbbell",
  fromLabel,
  toLabel,
  sort: sortProp = "none",
  higherIsBetter = true,
  change: changeProp = "absolute",
  highlight,
  color = 1,
  includeZero = false,
  height = 340,
  valueLabel,
  format: formatProp,
  formatPercent: formatPercentProp,
  locale,
  emptyState,
  labels,
  "aria-label": ariaLabel,
  className,
  ref: outerRef,
  ...rest
}: ChartRoot<DumbbellChartProps>) {
  const t = useMemo(() => ({ ...defaultDumbbellChartLabels, ...labels }), [labels]);
  const id = useId();
  const format = formatProp ?? defaultCompact(locale);
  const pct = formatPercentProp ?? defaultPercent(locale);
  const reduced = useSheenReducedMotion();
  const rootRef = useRef<HTMLDivElement>(null);
  const rootMerged = useMergedRef(rootRef, outerRef);
  const layerRef = useRef<SVGGElement>(null);
  const ghostRef = useRef<SVGGElement>(null);
  const [measureRef, width] = useElementWidth<HTMLDivElement>();
  const rtl = useChartDirection(rootRef);
  const play = useEntrance(rootRef, reduced);
  const input = useInputSource();
  const coarse = useCoarsePointer();
  const [active, setActive] = useState<string | null>(null);
  const pointer = usePointerReading<string>(active, setActive, input.fromPointer);
  const bounds = useHitBounds(width);
  // New data renders in the background (interruptible): the control that changed it answers at once.
  const data = useDeferredValue(dataProp);
  const sort = useDeferredValue(sortProp);
  const change = useDeferredValue(changeProp);
  const slope = variant === "slope";
  const fromName = fromLabel ?? t.from;
  const toName = toLabel ?? t.to;
  const highlightKey = highlight === undefined ? null : Array.isArray(highlight) ? highlight.join("\u0001") : highlight;
  const rows = useMemo(
    () => resolveRows(data, sort, highlightKey === null ? null : highlightKey.split("\u0001")),
    [data, sort, highlightKey],
  );
  const n = rows.length;
  const colors = useMemo(() => dumbbellColors(color), [color]);
  const colorsOf = useCallback((r: Pick<Row, "dimmed">) => (r.dimmed ? DIMMED : colors), [colors]);

  const signed = signedText;
  const changeText = useCallback(
    (r: Row) =>
      r.diff === 0
        ? t.noChange
        : change === "percent"
          ? Number.isFinite(r.ratio)
            ? signed(r.ratio, pct(r.ratio))
            : "–"
          : signed(r.diff, format(r.diff)),
    [t, change, pct, format, signed],
  );
  const tone = useCallback(
    (r: Row) =>
      r.diff === 0
        ? "fill-sheen-fg-muted"
        : r.diff > 0 === higherIsBetter
          ? "fill-sheen-success-text"
          : "fill-sheen-danger-text",
    [higherIsBetter],
  );

  const readoutFor = useCallback(
    (r: Row): Readout => {
      const c = colorsOf(r);
      const out: TooltipRow[] = [
        { label: toName, value: isolate(format(r.to)), color: c.to, kind: "rect" },
        { label: fromName, value: isolate(format(r.from)), color: c.from, kind: "rect" },
        {
          label: t.change,
          value: r.diff === 0 ? t.noChange : isolate(signed(r.diff, format(r.diff))),
          color: "transparent",
        },
      ];
      if (r.diff !== 0 && Number.isFinite(r.ratio))
        out.push({ label: t.percentChange, value: isolate(signed(r.ratio, pct(r.ratio))), color: "transparent" });
      return { title: r.label, rows: out };
    },
    [colorsOf, toName, fromName, format, pct, t, signed],
  );
  const rowH = coarse ? 44 : 36;
  // Touch screens dock the readout above the plot, unless the plot is too tall for that band to stay in view.
  const docked = useDockFits(width, slope ? height : n * rowH + 26);
  const dock = useMemo(() => (docked ? dockSpace(width, rows.map(readoutFor)) : 0), [docked, width, rows, readoutFor]);

  // Value domain.
  const [lo, hi] = useMemo(() => dumbbellDomain(rows, includeZero), [rows, includeZero]);

  const step = Math.min(0.06, 0.6 / Math.max(1, n));
  const act = active !== null ? rows.findIndex((r) => r.key === active) : -1;
  const actRow = act >= 0 ? rows[act] : undefined;
  const readout = actRow ? readoutFor(actRow) : undefined;

  /* ---------- Slope chart layout ---------- */
  const S = useMemo(
    () => (slope ? computeSlopeLayout({ rows, width, height, dock, valueLabel, lo, hi, format, rtl, n }) : null),
    [slope, width, dock, valueLabel, height, lo, hi, rows, format, rtl, n],
  );

  /* ---------- Dumbbell layout ---------- */
  const B = useMemo(
    () =>
      slope
        ? null
        : computeDumbbellLayout({
            rows,
            width,
            change,
            changeText,
            dock,
            n,
            rowH,
            valueLabel,
            formatProp,
            lo,
            hi,
            rtl,
          }),
    [slope, rows, width, change, changeText, dock, n, rowH, valueLabel, formatProp, lo, hi, rtl],
  );

  // Each row's numbers (where it sits and where its ends are), moved by one frame loop on data changes.
  const marks = useMemo(() => {
    const out = new Map<string, MarkState>();
    if (width <= 0) return out;
    rows.forEach((r, i) => {
      if (S) out.set(r.key, [S.sy(r.from), S.sy(r.to), S.leftY[i] ?? 0, S.rightY[i] ?? 0]);
      else if (B) out.set(r.key, [rowH * (i + 0.5), B.X(r.from), B.X(r.to)]);
    });
    return out;
  }, [rows, S, B, rowH, width]);
  const rowIndex = useMemo(() => new Map(rows.map((r, i) => [r.key, i])), [rows]);

  useMarkMotion(
    layerRef,
    ghostRef,
    marks,
    { play: play && width > 0, reduced, resetKey: width },
    {
      write: (el, s) => writeDumbbellMark(S, el, s),
      entrance: (s, key, el) => dumbbellEntrance(S, step, rowIndex.get(key) ?? 0, s, el),
      // Long lists (each row animates several parts) sweep in as one layer, in reading order.
      maxEntrance: slope ? 16 : 24,
      layerEntrance: () => ({
        keyframes: [
          { clipPath: rtl ? "inset(0 0 0 100%)" : "inset(0 100% 0 0)", opacity: 0.4 },
          { clipPath: "inset(0 0 0 0)", opacity: 1 },
        ],
        delay: 0.1,
        duration: duration.slower * 1.4,
      }),
    },
  );

  // The rows, rendered once per data set and size: reading a row never re-renders them.
  const rowLayer = useMemo(() => {
    if (width <= 0) return null;
    if (S) {
      return rows.map((r, i) => {
        const c = colorsOf(r);
        const y1 = S.sy(r.from);
        const y2 = S.sy(r.to);
        const gid = `${id}-s${i}`;
        const strong = highlightKey !== null && !r.dimmed;
        const name = fitText(r.label, S.nameW, 12, true);
        const shown = S.spreadOk || !r.dimmed;
        return (
          <g key={r.key} data-k={r.key}>
            <defs>
              <linearGradient
                data-part="grad"
                id={gid}
                gradientUnits="userSpaceOnUse"
                x1={S.xL}
                x2={S.xR}
                y1={y1}
                y2={y2}
              >
                <stop offset="0%" stopColor={c.from} />
                <stop offset="100%" stopColor={c.to} />
              </linearGradient>
            </defs>
            <g className={rowDimClass}>
              <path
                data-part="line"
                d={`M${S.xL},${y1.toFixed(1)} L${S.xR},${y2.toFixed(1)}`}
                fill="none"
                stroke={`url(#${gid})`}
                strokeWidth={2}
                strokeLinecap="round"
                pathLength={1}
                strokeDasharray="1 1"
                className="forced-color-adjust-none forced-colors:stroke-[CanvasText]"
              />
              <path
                data-part="from"
                d={dotPath(S.xL, y1, FROM_R)}
                fill={c.from}
                stroke="var(--sheen-chart-surface)"
                strokeWidth={2}
                style={centreOrigin}
                className="forced-color-adjust-none forced-colors:fill-[CanvasText]"
              />
              <path
                data-part="to"
                d={dotPath(S.xR, y2, TO_R)}
                fill={c.to}
                stroke="var(--sheen-chart-surface)"
                strokeWidth={2}
                style={centreOrigin}
                className="forced-color-adjust-none forced-colors:fill-[CanvasText]"
              />
              {shown && <SlopeLabels row={r} name={name} strong={strong} S={S} i={i} format={format} />}
            </g>
          </g>
        );
      });
    }
    if (!B) return null;
    return rows.map((r, i) => {
      const c = colorsOf(r);
      const xa = B.X(r.from);
      const xb = B.X(r.to);
      const strong = highlightKey !== null && !r.dimmed;
      const short = fitText(r.label, B.labelCol - 16, 12, true);
      return (
        <g key={r.key} data-k={r.key} transform={`translate(0 ${(rowH * (i + 0.5)).toFixed(1)})`}>
          <text
            x={rtl ? B.innerW + 12 : -12}
            dy="0.32em"
            textAnchor={rtl ? "start" : "end"}
            className={cn("text-xs", strong ? "fill-sheen-fg font-medium" : "fill-sheen-fg-muted")}
          >
            {short !== r.label && <title>{r.label}</title>}
            {short}
          </text>
          <g className={cn("forced-color-adjust-none", rowDimClass)}>
            {/* The bar between the ends brightens in the direction of travel. */}
            <path
              data-part="bar"
              d={barD(xa, xb)}
              fill={`url(#${id}-${r.to >= r.from ? "up" : "down"}-${r.dimmed ? "d" : "c"})`}
              style={{ transformBox: "fill-box", transformOrigin: xa <= xb ? "left center" : "right center" }}
              className="forced-colors:fill-[CanvasText]"
            />
            <path
              data-part="from"
              d={dotPath(xa, 0, FROM_R)}
              fill={c.from}
              stroke="var(--sheen-chart-surface)"
              strokeWidth={2}
              style={centreOrigin}
              className="forced-colors:fill-[CanvasText]"
            />
            <path
              data-part="to"
              d={dotPath(xb, 0, TO_R)}
              fill={c.to}
              stroke="var(--sheen-chart-surface)"
              strokeWidth={2}
              style={centreOrigin}
              className="forced-colors:fill-[CanvasText]"
            />
            {change !== "none" && (
              <ChangeText
                data-part="chg"
                row={r}
                x={rtl ? -10 : B.innerW + 10}
                rtl={rtl}
                text={changeText(r)}
                arrow={arrowOf(r)}
                tone={tone(r)}
              />
            )}
          </g>
        </g>
      );
    });
  }, [rows, S, B, width, id, highlightKey, colorsOf, format, rtl, rowH, change, changeText, tone]);

  const grid = useMemo(
    () => (B ? <DumbbellAxis layout={B} valueLabel={valueLabel} reduced={reduced} /> : null),
    [B, valueLabel, reduced],
  );

  if (n === 0) {
    return (
      <ChartEmpty height={slope ? height : 160} aria-label={ariaLabel} className={className}>
        {emptyState ?? t.noData}
      </ChartEmpty>
    );
  }

  function onKeyDown(event: React.KeyboardEvent, order: number[]) {
    const at = act >= 0 ? order.indexOf(act) : -1;
    let k: number | null | undefined;
    if (event.key === "ArrowDown") k = Math.min(n - 1, at + 1);
    else if (event.key === "ArrowUp") k = at < 0 ? 0 : Math.max(0, at - 1);
    else if (event.key === "Home") k = 0;
    else if (event.key === "End") k = n - 1;
    else if (event.key === "Escape" && act >= 0) k = null;
    if (k === undefined) return;
    event.preventDefault();
    input.fromKeyboard();
    setActive(k === null ? null : (rows[order[k] ?? 0]?.key ?? null));
  }

  const announcer = (
    <ChartAnnouncer
      text={input.announce(
        readout ? `${readout.title}: ${readout.rows.map((r) => `${r.label} ${r.value}`).join(", ")}` : "",
      )}
    />
  );
  const layer = (
    <g ref={layerRef} data-dim={act >= 0 ? "" : undefined} className="group" opacity={play ? undefined : 0}>
      {rowLayer}
    </g>
  );

  /* ---------------- Slope chart ---------------- */
  if (S) {
    const { top, innerH, xL, xR, sy, leftY, rightY, nameW } = S;

    function hitSlope(event: React.PointerEvent<SVGRectElement>, fresh = false) {
      const rect = bounds.rect(event.currentTarget, fresh);
      const px = event.clientX - rect.left;
      const py = event.clientY - rect.top - top;
      const k = clamp((px - Math.min(xL, xR)) / Math.max(1, Math.abs(xR - xL)), 0, 1);
      const kk = rtl ? 1 - k : k;
      let best = -1;
      let bestD = Infinity;
      rows.forEach((r, i) => {
        const y = sy(r.from) + (sy(r.to) - sy(r.from)) * kk;
        // Labels count too: a pointer on a name reads that line.
        const dy = Math.min(
          Math.abs(y - py),
          Math.abs((kk < 0.5 ? (leftY[i] ?? 0) : (rightY[i] ?? 0)) - py) +
            (px < Math.min(xL, xR) || px > Math.max(xL, xR) ? 0 : 6),
        );
        if (dy < bestD) {
          bestD = dy;
          best = i;
        }
      });
      return best >= 0 && bestD <= (event.pointerType === "mouse" ? 14 : 22) ? itemAt(rows, best).key : null;
    }

    const tipAnchor = actRow
      ? {
          x: Math.min(xL, xR),
          y: top + Math.min(sy(actRow.from), sy(actRow.to)) - 8,
          w: Math.abs(xR - xL),
          h: Math.abs(sy(actRow.to) - sy(actRow.from)) + 16,
        }
      : { x: 0, y: 0, w: 0, h: 0 };
    const ac = actRow ? colorsOf(actRow) : null;
    const ay1 = actRow ? sy(actRow.from) : 0;
    const ay2 = actRow ? sy(actRow.to) : 0;

    return (
      <div {...rest} ref={rootMerged} className={cn("relative w-full", className)}>
        <div ref={measureRef} className="relative w-full" style={{ height }}>
          {width > 0 && (
            <ChartFigure
              as="svg"
              width={width}
              height={height}
              roleDescription={t.roleDescription(true)}
              label={ariaLabel}
              description={resolveInstructions(t.instructions)}
              tabIndex={0}
              direction="ltr"
              onKeyDown={(e) => onKeyDown(e, S.orderTopDown)}
              onBlur={() => setActive(null)}
              className={cn("overflow-visible rounded-sheen-sm touch-pan-y touch-pinch-zoom", chartFocusClass)}
            >
              <defs>
                <GlowFilter
                  id={`${id}-glow`}
                  blur={4}
                  region={
                    actRow
                      ? { x: Math.min(xL, xR), y: Math.min(ay1, ay2), w: Math.abs(xR - xL), h: Math.abs(ay2 - ay1) }
                      : null
                  }
                />
                {actRow && ac && (
                  <linearGradient id={`${id}-active`} gradientUnits="userSpaceOnUse" x1={xL} x2={xR} y1={ay1} y2={ay2}>
                    <stop offset="0%" stopColor={ac.from} />
                    <stop offset="100%" stopColor={ac.to} />
                  </linearGradient>
                )}
              </defs>
              <g aria-hidden>
                {/* Column heads and axes. */}
                {[
                  { x: xL, name: fromName },
                  { x: xR, name: toName },
                ].map((col) => (
                  <g key={col.name}>
                    <line x1={col.x} x2={col.x} y1={top - 8} y2={top + innerH + 8} stroke="var(--sheen-border)" />
                    <text x={col.x} y={dock + 14} textAnchor="middle" className="fill-sheen-fg text-xs font-semibold">
                      {col.name}
                    </text>
                  </g>
                ))}
                {valueLabel && (
                  <text
                    x={width / 2}
                    y={height - 4}
                    textAnchor="middle"
                    className="fill-sheen-fg-muted text-2xs font-medium"
                  >
                    {valueLabel}
                  </text>
                )}

                <g transform={`translate(0,${top})`}>
                  {layer}
                  <g ref={ghostRef} />
                  {/* The line being read, at full strength over the others. */}
                  {actRow && ac && (
                    <g pointerEvents="none" className="forced-color-adjust-none">
                      <path
                        d={`M${xL},${ay1} L${xR},${ay2}`}
                        fill="none"
                        strokeWidth={6}
                        strokeLinecap="round"
                        style={{ stroke: glowColor(ac.to) }}
                        filter={`url(#${id}-glow)`}
                        className="forced-colors:hidden"
                      />
                      <path
                        d={`M${xL},${ay1} L${xR},${ay2}`}
                        fill="none"
                        stroke={`url(#${id}-active)`}
                        strokeWidth={3}
                        strokeLinecap="round"
                        className="forced-colors:stroke-[Highlight]"
                      />
                      <path
                        d={dotPath(xL, ay1, FROM_R)}
                        fill={ac.from}
                        stroke="var(--sheen-chart-surface)"
                        strokeWidth={2}
                        className="forced-colors:fill-[CanvasText]"
                      />
                      <path
                        d={dotPath(xR, ay2, TO_R * 1.2)}
                        fill={ac.to}
                        stroke="var(--sheen-chart-surface)"
                        strokeWidth={2}
                        className="forced-colors:fill-[CanvasText]"
                      />
                      <SlopeLabels
                        row={actRow}
                        name={fitText(actRow.label, nameW, 12, true)}
                        strong
                        S={S}
                        i={act}
                        format={format}
                        at={[leftY[act] ?? 0, rightY[act] ?? 0]}
                      />
                    </g>
                  )}
                  <rect
                    x={0}
                    y={-top + dock}
                    width={width}
                    height={innerH + top - dock + 8}
                    fill="transparent"
                    style={{ touchAction: "pan-y pinch-zoom" }}
                    onPointerEnter={bounds.reset}
                    onPointerDown={(e) => pointer.down(e, hitSlope(e, true))}
                    onPointerMove={(e) => pointer.move(e, hitSlope(e))}
                    onPointerUp={pointer.up}
                    onPointerLeave={pointer.leave}
                  />
                </g>
              </g>
            </ChartFigure>
          )}
          {docked && !readout && <DockHint height={dockHintHeight(dock)}>{t.hint}</DockHint>}
          {readout && (
            <ChartTip
              title={readout.title}
              rows={readout.rows}
              anchor={tipAnchor}
              bounds={{ w: width, h: height }}
              docked={docked}
              order={SLOPE_TIP}
            />
          )}
        </div>
        {announcer}
      </div>
    );
  }

  /* ---------------- Dumbbell ---------------- */
  // B is only null in the slope layout, which returned above.
  if (!B) return null;
  const { labelCol, top, chartH, innerH, M, innerW, X, originX } = B;
  const centre = (i: number) => rowH * (i + 0.5);

  function hitRow(event: React.PointerEvent<SVGRectElement>, fresh = false) {
    const rect = bounds.rect(event.currentTarget, fresh);
    return rows[clamp(Math.floor((event.clientY - rect.top) / rowH), 0, n - 1)]?.key ?? null;
  }

  let tipAnchor = { x: 0, y: 0, w: 0, h: 0 };
  if (actRow) {
    const a = Math.min(X(actRow.from), X(actRow.to)) - TO_R;
    const b = Math.max(X(actRow.from), X(actRow.to)) + TO_R;
    tipAnchor = { x: originX + a, y: top + centre(act) - rowH / 2 + 4, w: b - a, h: rowH - 8 };
  }
  const ac = actRow ? colorsOf(actRow) : null;
  const axa = actRow ? X(actRow.from) : 0;
  const axb = actRow ? X(actRow.to) : 0;

  return (
    <div {...rest} ref={rootMerged} className={cn("relative w-full", className)}>
      <div ref={measureRef} className="relative w-full" style={{ height: chartH }}>
        {width > 0 && (
          <ChartFigure
            as="svg"
            width={width}
            height={chartH}
            roleDescription={t.roleDescription(false)}
            label={ariaLabel}
            description={resolveInstructions(t.instructions)}
            tabIndex={0}
            direction="ltr"
            onKeyDown={(e) =>
              onKeyDown(
                e,
                rows.map((_, i) => i),
              )
            }
            onBlur={() => setActive(null)}
            className={cn("overflow-visible rounded-sheen-sm touch-pan-y touch-pinch-zoom", chartFocusClass)}
          >
            <defs>
              <GlowFilter
                id={`${id}-glow`}
                blur={4}
                region={
                  actRow ? { x: Math.min(axa, axb) - 4, y: centre(act) - 4, w: Math.abs(axb - axa) + 8, h: 8 } : null
                }
              />
              {(["up", "down"] as const).flatMap((dir) =>
                [false, true].map((dimmed) => {
                  const c = dimmed ? DIMMED : colors;
                  // Gradient runs from the "before" end to the "after" end on screen.
                  const rightward = (dir === "up") !== rtl;
                  return (
                    <linearGradient
                      key={`${dir}${dimmed}`}
                      id={`${id}-${dir}-${dimmed ? "d" : "c"}`}
                      x1={rightward ? 0 : 1}
                      x2={rightward ? 1 : 0}
                      y1={0}
                      y2={0}
                    >
                      <stop offset="0%" stopColor={c.from} />
                      <stop offset="100%" stopColor={c.to} />
                    </linearGradient>
                  );
                }),
              )}
            </defs>
            <g aria-hidden transform={`translate(${originX},${top})`}>
              {grid}

              {act >= 0 && (
                <rect
                  x={rtl ? -M.end + 4 : -M.start + 4}
                  y={centre(act) - rowH / 2 + 2}
                  width={width - 8}
                  height={rowH - 4}
                  rx={8}
                  fill="var(--sheen-hover)"
                  className="forced-colors:fill-none forced-colors:stroke-[Highlight]"
                />
              )}

              {layer}
              <g ref={ghostRef} />

              {/* The row being read, at full strength over the others. */}
              {actRow && ac && (
                <g pointerEvents="none" transform={`translate(0 ${centre(act)})`} className="forced-color-adjust-none">
                  <path
                    d={`M${axa},0 L${axb},0`}
                    fill="none"
                    strokeWidth={8}
                    strokeLinecap="round"
                    style={{ stroke: glowColor(ac.to) }}
                    filter={`url(#${id}-glow)`}
                    className="forced-colors:hidden"
                  />
                  <text
                    x={rtl ? innerW + 12 : -12}
                    dy="0.32em"
                    textAnchor={rtl ? "start" : "end"}
                    className={cn("text-xs fill-sheen-fg", highlightKey !== null && !actRow.dimmed && "font-medium")}
                  >
                    {fitText(actRow.label, labelCol - 16, 12, true)}
                  </text>
                  <path
                    d={barD(axa, axb)}
                    fill={`url(#${id}-${actRow.to >= actRow.from ? "up" : "down"}-${actRow.dimmed ? "d" : "c"})`}
                    className="forced-colors:fill-[CanvasText]"
                  />
                  <path
                    d={dotPath(axa, 0, FROM_R)}
                    fill={ac.from}
                    stroke="var(--sheen-chart-surface)"
                    strokeWidth={2}
                    className="forced-colors:fill-[CanvasText]"
                  />
                  <path
                    d={dotPath(axb, 0, TO_R * 1.2)}
                    fill={ac.to}
                    stroke="var(--sheen-chart-surface)"
                    strokeWidth={2}
                    className="forced-colors:fill-[CanvasText]"
                  />
                  {change !== "none" && (
                    <ChangeText
                      row={actRow}
                      x={rtl ? -10 : innerW + 10}
                      rtl={rtl}
                      text={changeText(actRow)}
                      arrow={arrowOf(actRow)}
                      tone={tone(actRow)}
                    />
                  )}
                </g>
              )}

              <rect
                x={rtl ? -M.end + 4 : -M.start + 4}
                y={0}
                width={width - 8}
                height={innerH}
                fill="transparent"
                style={{ touchAction: "pan-y pinch-zoom" }}
                onPointerEnter={bounds.reset}
                onPointerDown={(e) => pointer.down(e, hitRow(e, true))}
                onPointerMove={(e) => pointer.move(e, hitRow(e))}
                onPointerUp={pointer.up}
                onPointerLeave={pointer.leave}
              />
            </g>
          </ChartFigure>
        )}
        {docked && !readout && <DockHint height={dockHintHeight(dock)}>{t.hint}</DockHint>}
        {readout && (
          <ChartTip
            title={readout.title}
            rows={readout.rows}
            anchor={tipAnchor}
            bounds={{ w: width, h: chartH }}
            docked={docked}
            order={TIP}
            minLeft={rtl ? 0 : M.start}
          />
        )}
      </div>
      {announcer}
    </div>
  );
}

"use client";

import { AnimatePresence, motion } from "motion/react";

import { duration } from "../../motion/tokens";
import { changeEase, exitTransition } from "../chart-utils";
import { textWidth } from "../chart-pointer";
import { edgeAnchor } from "../histogram/model";
import type { computeDumbbellLayout } from "./layout";

type DumbbellLayout = NonNullable<ReturnType<typeof computeDumbbellLayout>>;

/**
 * The dumbbell's value axis: gridlines with tick labels that glide to their new place when the scale changes
 * and fade as they leave, plus the axis title. Instant under reduced motion.
 * @internal
 */
export function DumbbellAxis({
  layout: B,
  valueLabel,
  reduced,
}: {
  layout: DumbbellLayout;
  valueLabel?: string;
  reduced: boolean;
}) {
  const instant = { duration: 0 };
  const morph = reduced ? instant : { duration: duration.slow, ease: changeEase };
  return (
    <>
      {valueLabel && (
        <text
          x={B.innerW / 2}
          y={B.innerH + 40}
          textAnchor="middle"
          className="fill-sheen-fg-muted text-2xs font-medium"
        >
          {valueLabel}
        </text>
      )}
      <AnimatePresence initial={false}>
        {B.ticks.map((tk, ti) => {
          const p = B.X(tk);
          const text = B.fmtAxis(tk);
          return (
            <motion.g
              key={`t${tk}`}
              initial={{ opacity: 0, x: p }}
              animate={{ opacity: 1, x: p }}
              exit={{ opacity: 0, transition: reduced ? instant : exitTransition }}
              transition={{ x: morph, opacity: reduced ? instant : { duration: duration.base } }}
            >
              <line y1={-4} y2={B.innerH} stroke={tk === 0 ? "var(--sheen-border)" : "var(--sheen-chart-grid)"} />
              {B.xShown.has(ti) && (
                <text
                  y={B.innerH + 18}
                  textAnchor={edgeAnchor(p, textWidth(text), B.axisLo, B.axisHi)}
                  className="fill-sheen-fg-muted text-2xs tabular-nums"
                >
                  {text}
                </text>
              )}
            </motion.g>
          );
        })}
      </AnimatePresence>
    </>
  );
}

import { fitTicks } from "../chart-fit";
import { axisFormat, clamp, itemAt, linear } from "../chart-utils";
import { textWidth } from "../chart-pointer";
import { axisLabelsShown } from "../histogram/model";
import { chartMirror } from "../kits/histogram-kit/kit";
import { arrowOf, spreadLabels, type Row } from "./model";

/** The value domain `[lo, hi]` of the rows, widened to include zero when asked. @internal */
export function dumbbellDomain(rows: readonly Row[], includeZero: boolean): [number, number] {
  let a = Infinity;
  let b = -Infinity;
  for (const r of rows) {
    a = Math.min(a, r.from, r.to);
    b = Math.max(b, r.from, r.to);
  }
  if (!Number.isFinite(a)) [a, b] = [0, 1];
  if (includeZero) {
    a = Math.min(a, 0);
    b = Math.max(b, 0);
  }
  return a === b ? [a - 1, b + 1] : [a, b];
}

/** Layout of the slope variant: two columns, the value scale and the de-overlapped label positions. @internal */
export function computeSlopeLayout(p: {
  rows: Row[];
  width: number;
  height: number;
  dock: number;
  valueLabel: string | undefined;
  lo: number;
  hi: number;
  format: (v: number) => string;
  rtl: boolean;
  n: number;
}) {
  const { rows, width, height, dock, valueLabel, lo, hi, format, rtl, n } = p;
  const narrow = width < 520;
  const top = 30 + dock;
  const bottom = 16 + (valueLabel ? 18 : 0);
  const innerH = Math.max(0, height - top - bottom);
  const sy = linear(lo, hi, innerH, 0);
  const widestName = rows.reduce((m, r) => Math.max(m, textWidth(r.label, 12, true)), 0);
  const valueW = rows.reduce(
    (m, r) => Math.max(m, textWidth(format(r.from), 12, true), textWidth(format(r.to), 12, true)),
    0,
  );
  // Names sit outside the left column (and the right one on wide charts), values next to the dots.
  const nameW = Math.min(widestName, Math.max(36, width * (narrow ? 0.34 : 0.22)));
  const sideL = nameW + valueW + 22;
  const sideR = (narrow ? 0 : nameW + 8) + valueW + 22;
  const xL = rtl ? width - sideL : sideL;
  const xR = rtl ? sideR : width - sideR;
  const gap = 15;
  const spreadOk = n * gap <= innerH + gap;
  const leftY = spreadLabels(
    rows.map((r) => sy(r.from)),
    gap,
    0,
    innerH,
  );
  const rightY = spreadLabels(
    rows.map((r) => sy(r.to)),
    gap,
    0,
    innerH,
  );
  const orderTopDown = rows.map((_, i) => i).sort((a, b) => sy(itemAt(rows, a).to) - sy(itemAt(rows, b).to));
  return { narrow, top, innerH, sy, nameW, xL, xR, spreadOk, leftY, rightY, orderTopDown, sideDir: rtl ? -1 : 1 };
}

/** Layout of the dumbbell variant: name column, change column, value axis and its ticks. @internal */
export function computeDumbbellLayout(p: {
  rows: Row[];
  width: number;
  change: string;
  changeText: (r: Row) => string;
  dock: number;
  n: number;
  rowH: number;
  valueLabel: string | undefined;
  formatProp: ((v: number) => string) | undefined;
  lo: number;
  hi: number;
  rtl: boolean;
}) {
  const { rows, width, change, changeText, dock, n, rowH, valueLabel, formatProp, lo, hi, rtl } = p;
  // A name column as wide as the widest name, up to a third of the chart (40% on narrow ones; longer names are cut to fit).
  const widestName = rows.reduce((m, r) => Math.max(m, textWidth(r.label, 12, true)), 0);
  const labelCol = clamp(Math.ceil(widestName) + 16, 44, Math.max(44, Math.floor(width * (width < 400 ? 0.4 : 0.34))));
  // Change column: "▲ +12%" in 12px medium text, after a 10px gap (and a hair to spare).
  const changeW =
    change === "none"
      ? 0
      : rows.reduce(
          (m, r) => Math.max(m, textWidth(`${arrowOf(r) ? `${arrowOf(r)} ` : ""}${changeText(r)}`, 12, true)),
          0,
        ) + 14;
  const top = 8 + dock;
  const chartH = n * rowH + top + 26 + (valueLabel ? 20 : 0);
  const innerH = n * rowH;
  const M = { start: labelCol, end: Math.max(16, changeW) };
  const innerW = Math.max(0, width - M.start - M.end);
  const fmtAxis = axisFormat(formatProp);
  const ticks = fitTicks(lo, hi, { length: Math.max(0, innerW - 16), axis: "x", format: fmtAxis });
  const t0 = ticks[0] ?? lo;
  const t1 = ticks[ticks.length - 1] ?? hi;
  const sx = linear(t0, t1, 8, Math.max(8, innerW - 8));
  const mirror = chartMirror(rtl, innerW);
  const X = (v: number) => mirror.x(sx(v));
  // Value labels stay off the name column (it swaps sides right to left).
  const axisLo = rtl ? -M.end : -12;
  const axisHi = rtl ? innerW + 12 : innerW + M.end;
  const xShown = axisLabelsShown(
    ticks.map((tk) => ({ x: X(tk), text: fmtAxis(tk) })),
    axisLo,
    axisHi,
  );
  return {
    labelCol,
    top,
    chartH,
    innerH,
    M,
    innerW,
    fmtAxis,
    ticks,
    X,
    originX: rtl ? M.end : M.start,
    axisLo,
    axisHi,
    xShown,
  };
}

import { type ReactNode } from "react";

import { type LegendItem } from "../chart-parts";
import { clamp, num, slotColor, type ChartColor, type ChartInstructions, itemAt } from "../chart-utils";
import { hueMix, type ChartTipSide } from "../heatmap";
import { CONTEXT_GREY } from "../kits/histogram-kit/kit";

/** One row of a DumbbellChart: a label and the values it moves from and to. */
export type DumbbellItem = {
  label: string;
  /** The "before" value. */
  from: number;
  /** The "after" value. */
  to: number;
};

/**
 * Every string DumbbellChart speaks or shows, so it can be translated: pass a `Partial` as the
 * `labels` prop. Entries that need a value are functions.
 */
export type DumbbellChartLabels = {
  roleDescription: (slope: boolean) => string;
  instructions: ChartInstructions;
  hint: string;
  /** Default names of the two ends when `fromLabel` / `toLabel` aren't given. */
  from: string;
  to: string;
  change: string;
  /** Percent change row label. */
  percentChange: string;
  /** A change of zero. */
  noChange: string;
  item: string;
  noData: string;
};

/**
 * The built-in English strings of DumbbellChart; spread it into your own `labels` and change what you
 * need. This module is a client module, so use it from client code, not from a Server Component.
 */
export const defaultDumbbellChartLabels: DumbbellChartLabels = {
  roleDescription: (slope) => (slope ? "slope chart" : "dumbbell chart"),
  instructions: "Use the up and down arrow keys to read each item.",
  hint: "Tap a row to read it",
  from: "Before",
  to: "After",
  change: "Change",
  percentChange: "% change",
  noChange: "No change",
  item: "Item",
  noData: "No data",
};

/**
 * Props of DumbbellChart. The component's own doc comment describes its behaviour, keyboard use and
 * accessibility.
 */
export type DumbbellChartProps = {
  /** Takes one item per row: { label, from, to }. */
  data: readonly DumbbellItem[];
  /** "dumbbell": a row per item, a dot at each end. "slope": two columns joined by a line per item. */
  variant?: "dumbbell" | "slope";
  /** Sets the name of the "before" end, e.g. "2024". */
  fromLabel?: string;
  /** Sets the name of the "after" end, e.g. "2025". */
  toLabel?: string;
  /** Order of the items. "change" puts the biggest rise first. */
  sort?: "none" | "to" | "from" | "change";
  /** Is a rise good (revenue) or bad (costs, churn)? Picks the status colour of the change. Default true. */
  higherIsBetter?: boolean;
  /** Show each item's change: "absolute" (+12), "percent" (+8%), or "none". Default "absolute". */
  change?: "absolute" | "percent" | "none";
  /** Emphasise these items (by label); the rest step back to grey. */
  highlight?: string | string[];
  /** Palette slot (1–8): the "after" dot in full, the "before" dot a lighter shade of it. Default 1. */
  color?: ChartColor;
  /** Keep 0 on the value axis. */
  includeZero?: boolean;
  /** Height of a slope chart. Dumbbell rows grow with the items. */
  height?: number;
  /** Names the value axis. */
  valueLabel?: string;
  /** Formats a value for the labels, tooltips and data table: takes the number, returns the text shown. Default: formatCompact in `locale`. */
  format?: (n: number) => string;
  /** Formats percent changes (0.08 → "8%"). Default: percentages in `locale`. */
  formatPercent?: (ratio: number) => string;
  /** Locale of the default number formats. Default "en". */
  locale?: string;
  /** Shown when there is nothing to plot. */
  emptyState?: ReactNode;
  /** Override the chart's strings (i18n). */
  labels?: Partial<DumbbellChartLabels>;
  /** Names the chart for assistive tech (required). */
  "aria-label": string;
  /** Adds extra classes to the outer element. */
  className?: string;
};

/** The radius of the start dot, in pixels. @internal */
export const FROM_R = 5;
/** The radius of the end dot, in pixels. @internal */
export const TO_R = 6.5;
/**
 * Ends of an item that isn't highlighted: two light greys (the "before" one paler) that step back
 * behind the highlighted items instead of out-weighing them.
 */
export const DIMMED = {
  from: "light-dark(color-mix(in oklab, var(--sheen-fg-subtle) 42%, var(--sheen-chart-surface)), color-mix(in oklab, var(--sheen-fg-subtle) 46%, var(--sheen-chart-surface)))",
  to: CONTEXT_GREY,
};
/** The tooltip side order. @internal */
export const TIP: readonly ChartTipSide[] = ["below", "above", "right", "left"];

/**
 * The two shades of a dumbbell: the "before" end is a paler step of the "after" hue. On light
 * surfaces that's a tint towards the surface; on dark ones a step towards the text colour, so it
 * stays visible (a tint towards a dark surface would sink into it).
 *
 * @see /charts/dumbbell
 */
export function dumbbellColors(color: ChartColor = 1) {
  return {
    from: `light-dark(${hueMix(color, 0.42)}, color-mix(in oklab, ${slotColor(color)} 55%, var(--sheen-fg-muted)))`,
    to: slotColor(color),
  };
}

/** Legend items for a dumbbell or slope chart: the two ends.
 *
 * @see /charts/dumbbell
 */
export function dumbbellLegend(
  fromLabel = defaultDumbbellChartLabels.from,
  toLabel = defaultDumbbellChartLabels.to,
  color: ChartColor = 1,
): LegendItem[] {
  const c = dumbbellColors(color);
  return [
    { label: fromLabel, color: c.from, kind: "rect" },
    { label: toLabel, color: c.to, kind: "rect" },
  ];
}

/** One dumbbell row with its start and end values and colour. @internal */
export type Row = {
  key: string;
  label: string;
  from: number;
  to: number;
  diff: number;
  ratio: number;
  dimmed: boolean;
};

/** Resolves the data into rows with finite values, colours and sort order. @internal */
export function resolveRows(
  data: readonly DumbbellItem[],
  sort: DumbbellChartProps["sort"],
  highlight: string[] | null,
): Row[] {
  const seen = new Map<string, number>();
  const rows = data.map((d) => {
    const n = seen.get(d.label) ?? 0;
    seen.set(d.label, n + 1);
    const from = num(d.from);
    const to = num(d.to);
    return {
      key: `${d.label}\u0000${n}`,
      label: d.label,
      from,
      to,
      diff: to - from,
      ratio: from !== 0 ? (to - from) / Math.abs(from) : NaN,
      dimmed: highlight !== null && !highlight.includes(d.label),
    };
  });
  if (sort === "to") return rows.sort((a, b) => b.to - a.to);
  if (sort === "from") return rows.sort((a, b) => b.from - a.from);
  if (sort === "change") return rows.sort((a, b) => b.diff - a.diff);
  return rows;
}

/**
 * Spreads label positions apart so no two sit closer than `gap`, keeping their order and staying
 * within [lo, hi]: overlapping labels form a cluster centred on their wanted positions (the classic
 * slope-chart label layout). Returns positions in the input order.
 */
export function spreadLabels(wanted: number[], gap: number, lo: number, hi: number): number[] {
  const order = wanted.map((y, i) => ({ y, i })).sort((a, b) => a.y - b.y || a.i - b.i);
  type Cluster = { items: { y: number; i: number }[]; top: number };
  const clusters: Cluster[] = [];
  const centre = (c: Cluster) => c.items.reduce((s, it) => s + it.y, 0) / c.items.length;
  const place = (c: Cluster) => {
    const span = (c.items.length - 1) * gap;
    c.top = clamp(centre(c) - span / 2, lo, Math.max(lo, hi - span));
  };
  for (const it of order) {
    const c: Cluster = { items: [it], top: it.y };
    place(c);
    clusters.push(c);
    // Merge backwards while the newest cluster overlaps the one before it.
    while (clusters.length > 1) {
      const last = itemAt(clusters, clusters.length - 1);
      const prev = itemAt(clusters, clusters.length - 2);
      if (prev.top + (prev.items.length - 1) * gap + gap <= last.top + 1e-6) break;
      prev.items.push(...last.items);
      clusters.pop();
      place(prev);
    }
  }
  const out = new Array<number>(wanted.length);
  for (const c of clusters) c.items.forEach((it, k) => (out[it.i] = c.top + k * gap));
  return out;
}

/** A dot as one path (so a data change morphs its `d`, never cx / cy). */
/** The direction glyph of a row's change (none when it is unchanged). */
export function arrowOf(r: Row) {
  return r.diff > 0 ? "▲" : r.diff < 0 ? "▼" : "";
}

/** A dot as one SVG path, so a data change morphs `d`. @internal */
export function dotPath(cx: number, cy: number, r: number) {
  const f = (n: number) => n.toFixed(2);
  return `M${f(cx - r)},${f(cy)} a${f(r)},${f(r)} 0 1,0 ${f(2 * r)},0 a${f(r)},${f(r)} 0 1,0 ${f(-2 * r)},0 Z`;
}
/** The 3px bar between a dumbbell's ends, in its row's own coordinates (the row is centred on y = 0). */
export function barD(xa: number, xb: number) {
  const left = Math.min(xa, xb);
  const len = Math.abs(xb - xa);
  return `M${left.toFixed(1)},-1.5 h${len.toFixed(1)} v3 h${(-len).toFixed(1)} Z`;
}
/** Finds the SVG element of a named `data-part` inside an element. @internal */
export const part = (el: Element, name: string) => el.querySelector<SVGElement>(`[data-part="${name}"]`);
/** Classes of the marks inside a row: they step back while another row is read (one opacity change per row). */
export const rowDimClass =
  "transition-opacity duration-(--sheen-duration-fast) ease-sheen-out motion-reduced:transition-none group-data-dim:opacity-35 forced-colors:group-data-dim:opacity-50";
/** The style that scales or rotates an SVG element around its own centre. @internal */
export const centreOrigin = { transformBox: "fill-box", transformOrigin: "center" } as const;

import type { MarkState } from "../kits/histogram-kit/kit";
import { duration } from "../../motion/tokens";
import { springEasing } from "../kits/histogram-kit/kit";
import { easeOut } from "./parts";
import { barD, dotPath, FROM_R, part, TO_R } from "./model";

/** The slope layout's column x positions, the part of it the mark writer needs. @internal */
export type SlopeColumns = { xL: number; xR: number } | null;

/** Writes one row's animated numbers into its element (slope lines or dumbbell bars). @internal */
export function writeDumbbellMark(S: SlopeColumns, el: SVGElement, s: MarkState) {
  if (S) {
    const [y1 = 0, y2 = 0, ly = 0, ry = 0] = s;
    part(el, "line")?.setAttribute("d", `M${S.xL},${y1.toFixed(1)} L${S.xR},${y2.toFixed(1)}`);
    const grad = part(el, "grad");
    grad?.setAttribute("y1", y1.toFixed(1));
    grad?.setAttribute("y2", y2.toFixed(1));
    part(el, "from")?.setAttribute("d", dotPath(S.xL, y1, FROM_R));
    part(el, "to")?.setAttribute("d", dotPath(S.xR, y2, TO_R));
    part(el, "lt")?.setAttribute("transform", `translate(0 ${ly.toFixed(1)})`);
    part(el, "rt")?.setAttribute("transform", `translate(0 ${ry.toFixed(1)})`);
    return;
  }
  const [y = 0, xa = 0, xb = 0] = s;
  el.setAttribute("transform", `translate(0 ${y.toFixed(1)})`);
  part(el, "bar")?.setAttribute("d", barD(xa, xb));
  part(el, "from")?.setAttribute("d", dotPath(xa, 0, FROM_R));
  part(el, "to")?.setAttribute("d", dotPath(xb, 0, TO_R));
}

/** The first-view entrance of one row: the "before" dot pops, then the "after" end lands. @internal */
export function dumbbellEntrance(S: SlopeColumns, step: number, i: number, s: MarkState, el: SVGElement) {
  const pop = { duration: 0.35, easing: springEasing() };
  if (S) {
    // The line draws left to right; the "before" dot and label pop first, the "after" ones land with the line.
    return [
      {
        target: part(el, "from"),
        keyframes: [{ transform: "scale(0)" }, { transform: "none" }],
        delay: 0.05 + i * step,
        ...pop,
      },
      {
        target: part(el, "lt"),
        keyframes: [{ opacity: 0 }, { opacity: 1 }],
        delay: 0.05 + i * step,
        duration: duration.base,
      },
      {
        target: part(el, "line"),
        keyframes: [{ strokeDashoffset: 1 }, { strokeDashoffset: 0 }],
        delay: 0.25 + i * step,
        duration: duration.slower,
      },
      {
        target: part(el, "to"),
        keyframes: [{ transform: "scale(0)" }, { transform: "none" }],
        delay: 0.25 + i * step + duration.slower * 0.8,
        ...pop,
      },
      {
        target: part(el, "rt"),
        keyframes: [{ opacity: 0 }, { opacity: 1 }],
        delay: 0.25 + i * step + duration.slower * 0.8,
        duration: duration.base,
      },
    ];
  }
  // The "before" dot pops in, then the "after" dot travels out of it, drawing the bar behind it.
  const [, xa = 0, xb = 0] = s;
  const travel = (xa - xb).toFixed(1);
  return [
    {
      target: part(el, "from"),
      keyframes: [{ transform: "scale(0)" }, { transform: "none" }],
      delay: 0.05 + i * step,
      ...pop,
    },
    {
      target: part(el, "bar"),
      keyframes: [{ transform: "scaleX(0)" }, { transform: "none" }],
      delay: 0.25 + i * step,
      duration: duration.slower,
    },
    {
      target: part(el, "to"),
      keyframes: [
        { transform: `translateX(${travel}px) scale(0)`, easing: easeOut() },
        { transform: `translateX(${travel}px) scale(1)`, offset: 0.25, easing: easeOut() },
        { transform: "translateX(0px) scale(1)" },
      ],
      delay: 0.05 + i * step,
      duration: 0.2 + duration.slower,
      easing: "linear",
    },
    {
      target: part(el, "chg"),
      keyframes: [{ opacity: 0 }, { opacity: 1 }],
      delay: 0.25 + i * step + duration.slower * 0.8,
      duration: duration.base,
    },
  ];
}

import { cn } from "../../lib/cn";
import { enterEase } from "../chart-utils";
import { type ChartTipSide } from "../heatmap";
import { type Row } from "./model";

/** The tooltip side order of the slope layout. @internal */
export const SLOPE_TIP: readonly ChartTipSide[] = ["right", "left", "below", "above"];
/** The enter easing as a CSS `cubic-bezier` string, built at call time so no client-only value is read at import. @internal */
export const easeOut = (): string => `cubic-bezier(${enterEase.join(",")})`;

/** A dumbbell row's change: ▲ / ▼ and the signed difference, in a success or danger tone. */
export function ChangeText({
  row,
  x,
  rtl,
  text,
  arrow,
  tone,
  ...rest
}: {
  row: Row;
  x: number;
  rtl: boolean;
  text: string;
  arrow: string;
  tone: string;
  "data-part"?: string;
}) {
  return (
    <text
      {...rest}
      x={x}
      dy="0.32em"
      textAnchor={rtl ? "end" : "start"}
      className={cn("text-xs font-medium tabular-nums", tone)}
    >
      {arrow && <tspan aria-hidden>{arrow} </tspan>}
      {text}
    </text>
  );
}

/** The computed geometry of the slope layout. @internal */
export type SlopeLayout = {
  xL: number;
  xR: number;
  leftY: number[];
  rightY: number[];
  narrow: boolean;
  sideDir: number;
};

/** A slope line's two labels: the name and "before" value on the left, the "after" value (and the name on wide charts) on the right. */
export function SlopeLabels({
  row,
  name,
  strong,
  S,
  i,
  format,
  at,
}: {
  row: Row;
  name: string;
  strong: boolean;
  S: SlopeLayout;
  i: number;
  format: (n: number) => string;
  at?: [number, number];
}) {
  const [ly, ry] = at ?? [S.leftY[i] ?? 0, S.rightY[i] ?? 0];
  const rtl = S.sideDir < 0;
  return (
    <>
      <text
        data-part="lt"
        x={S.xL - 12 * S.sideDir}
        dy="0.32em"
        transform={`translate(0 ${ly.toFixed(1)})`}
        textAnchor={rtl ? "start" : "end"}
        className="text-xs"
      >
        <tspan className={strong ? "fill-sheen-fg font-medium" : "fill-sheen-fg-muted"}>
          {name}
          {name !== row.label && <title>{row.label}</title>}
        </tspan>
        <tspan className="fill-sheen-fg font-medium tabular-nums" dx={6}>
          {format(row.from)}
        </tspan>
      </text>
      <text
        data-part="rt"
        x={S.xR + 12 * S.sideDir}
        dy="0.32em"
        transform={`translate(0 ${ry.toFixed(1)})`}
        textAnchor={rtl ? "end" : "start"}
        className="text-xs"
      >
        <tspan className="fill-sheen-fg font-semibold tabular-nums">{format(row.to)}</tspan>
        {!S.narrow && (
          <tspan className={strong ? "fill-sheen-fg font-medium" : "fill-sheen-fg-muted"} dx={6}>
            {name}
          </tspan>
        )}
      </text>
    </>
  );
}

import { ChartValueTable, defaultCompact, defaultPercent } from "../heatmap";
import { isolate } from "../chart-pointer";
import { signedText } from "../kits/histogram-kit/kit";
import { defaultDumbbellChartLabels, type DumbbellChartProps, resolveRows } from "./model";

/* ---------- Table view ---------- */

/**
 * Props of DumbbellTable, the table view of the chart: the chart's data and formatting props plus a
 * hidden `caption` for screen readers.
 */
export type DumbbellTableProps = Pick<
  DumbbellChartProps,
  "data" | "sort" | "fromLabel" | "toLabel" | "format" | "formatPercent" | "locale" | "labels"
> & {
  /** Hidden caption that names the table for screen readers. */
  caption?: string;
  /** Adds extra classes to the outer element. */
  className?: string;
};

/**
 * Every item's two values, its change and its percent change.
 *
 * Props: the chart's `data`, `sort`, `fromLabel`, `toLabel`, `format`, `formatPercent`, `locale` and `labels`, plus `caption` (hidden, names the table) and `className`. A real table: each item's two values, its change and its percent change. Static (no motion). Pass it to `ChartCard table`.
 *
 * @example
 * ```tsx
 * import { DumbbellTable } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <DumbbellTable data={[{ label: "Checkout", from: 3.2, to: 4.1 }]} fromLabel="Q1" toLabel="Q2" caption="Satisfaction score, Q1 to Q2" />
 *   );
 * }
 * ```
 *
 * @see /charts/dumbbell
 */
export function DumbbellTable({
  data,
  sort = "none",
  fromLabel,
  toLabel,
  format: formatProp,
  formatPercent: formatPercentProp,
  locale,
  labels,
  caption,
  className,
}: DumbbellTableProps) {
  const t = { ...defaultDumbbellChartLabels, ...labels };
  const format = formatProp ?? defaultCompact(locale);
  const pct = formatPercentProp ?? defaultPercent(locale);
  const rows = resolveRows(data, sort, null);
  const signed = signedText;
  return (
    <ChartValueTable
      caption={caption}
      className={className}
      emptyState={t.noData}
      columns={[
        { label: t.item },
        { label: fromLabel ?? t.from },
        { label: toLabel ?? t.to },
        { label: t.change },
        { label: t.percentChange },
      ]}
      // Numbers are isolated so right-to-left pages keep each one whole ("−4", not "4−").
      rows={rows.map((r) => [
        r.label,
        isolate(format(r.from)),
        isolate(format(r.to)),
        r.diff === 0 ? t.noChange : isolate(signed(r.diff, format(r.diff))),
        Number.isFinite(r.ratio) && r.diff !== 0 ? isolate(signed(r.ratio, pct(r.ratio))) : "–",
      ])}
    />
  );
}

